 function syncSelection(root){const s=tableState(root),checks=[...root.querySelectorAll('[data-data-check]')],checked=checks.filter(c=>s.selected.has(Number(c.dataset.dataCheck)));const all=root.querySelector('[data-data-all]');if(all){all.checked=checks.length>0&&checked.length===checks.length;all.indeterminate=checked.length>0&&checked.length<checks.length}const summary=root.querySelector('[data-selection-summary]');if(summary)summary.textContent=s.selected.size+' selected';}
 function position(popup,trigger,side='bottom'){if(!trigger)return;if(popup.matches('.sx-select-options'))popup.style.width=trigger.getBoundingClientRect().width+'px';const r=trigger.getBoundingClientRect(),p=popup.getBoundingClientRect(),gap=6;let left=r.left,top=r.bottom+gap;if(side==='top')top=r.top-p.height-gap;if(side==='right'){left=r.right+gap;top=r.top}if(side==='left'){left=r.left-p.width-gap;top=r.top}if(popup.getAttribute('role')==='tooltip'){if(side==='top'||side==='bottom')left=r.left+(r.width-p.width)/2;else top=r.top+(r.height-p.height)/2;if(side==='top'&&top<8)top=r.bottom+gap;}if(top+p.height>innerHeight-8)top=r.top-p.height-gap;popup.style.left=Math.max(8,Math.min(left,innerWidth-p.width-8))+'px';popup.style.top=Math.max(8,Math.min(top,innerHeight-p.height-8))+'px';}
