 root.querySelector('[data-calendar-content]').innerHTML=`<div class="sx-calendar-header">${button(icon('chevron-left'),'data-month-step="-1" aria-label="Previous month"','ghost')}<strong aria-live="polite">${heading}</strong>${button(icon('chevron-right'),'data-month-step="1" aria-label="Next month"','ghost')}</div><div class="sx-calendar-grid" role="grid" aria-label="${heading}"><div role="row">${['Su','Mo','Tu','We','Th','Fr','Sa'].map(d=>`<span class="sx-weekday" role="columnheader">${d}</span>`).join('')}</div>${rows.join('')}</div>`;
